// ─────────────────────────────────────────────────────────────
// Call RankReady SaaS API to generate SEO blog content
// Endpoint: POST https://rank-ready-sag.lovable.app/api/generate
// Returns: SSE stream with {type, delta, wordCount} chunks
// ─────────────────────────────────────────────────────────────

const idea = $input.first().json.Idea;

// Configure generation parameters
const requestBody = {
  topic: idea,
  audience: 'business owners and agencies interested in AI automation',
  tone: 'Expert',
  wordCount: 1200
};

const response = await fetch('https://rank-ready-sag.lovable.app/api/generate', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify(requestBody)
});

if (!response.ok) {
  const errorBody = await response.text();
  throw new Error(`RankReady API error (${response.status}): ${errorBody}`);
}

const rawText = await response.text();

// Parse SSE stream: each line is "data: {JSON}\n"
const lines = rawText.split('\n').filter(l => l.startsWith('data: '));
let fullContent = '';
let wordCount = 0;

for (const line of lines) {
  try {
    const data = JSON.parse(line.substring(6)); // remove 'data: ' prefix
    if (data.delta) fullContent += data.delta;
    if (data.wordCount) wordCount = data.wordCount;
  } catch (e) {
    // skip malformed lines
  }
}

if (!fullContent) {
  throw new Error('RankReady returned empty content');
}

// Extract title from the first <h1> tag
const titleMatch = fullContent.match(/<h1[^>]*>(.*?)<\/h1>/i);
const title = titleMatch ? titleMatch[1].replace(/<[^>]*>/g, '').trim() : idea;

// Generate URL slug from title
const slug = title
  .toLowerCase()
  .replace(/[^a-z0-9\s-]/g, '')
  .replace(/\s+/g, '-')
  .replace(/-+/g, '-')
  .substring(0, 80);

return [{
  json: {
    content: fullContent,
    title: title,
    slug: slug,
    wordCount: wordCount,
    topic: idea
  }
}];

// Parse WordPress response and prepare data for downstream nodes
// This replaces the original Parse1 node

const wpResponse = $input.first().json;
const generateData = $('RankReady — Generate Content').first().json;

const postId = wpResponse.id;
const postUrl = wpResponse.link || `https://YOUR_WORDPRESS_SITE/?p=${postId}`;

// Generate a 3-line summary from the content
const content = generateData.content || '';
const plainText = content.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
const sentences = plainText.split(/[.!?]+/).filter(s => s.trim().length > 20);

const summaryLines = [];
if (sentences.length >= 3) {
  summaryLines.push(sentences[0].trim());
  summaryLines.push(sentences[Math.floor(sentences.length / 2)].trim());
  summaryLines.push(sentences[sentences.length - 1].trim());
} else {
  summaryLines.push(generateData.topic);
  summaryLines.push(plainText.substring(0, 150));
  summaryLines.push(`${generateData.wordCount} words generated via RankReady`);
}

return [{
  json: {
    summary: summaryLines.join(' | '),
    post: {
      post_id: postId,
      post_url: postUrl
    },
    status: 'success',
    title: generateData.title,
    slug: generateData.slug,
    wordCount: generateData.wordCount
  }
}];

