const raw = $input.first().json.choices[0].message.content;

const diagram = raw
  .trim()
  .replace(/\(([^\[\]()]+)\)/g, '- $1');

const encoded = Buffer.from(diagram)
  .toString('base64')
  .replace(/\+/g, '-')
  .replace(/\//g, '_')
  .replace(/=/g, '');

return [{ json: { encoded } }];

const postData = $('Get Post Content').first().json;
const uploadData = $('Upload Diagram to WP').first().json;

if (!postData) throw new Error('Get Post Content node returned nothing');
if (!uploadData) throw new Error('Upload Diagram to WP node returned nothing');

const existingContent = postData.content.rendered;
const imageUrl = uploadData.source_url;
const imageId = uploadData.id;

if (!existingContent) throw new Error('content.rendered is empty');
if (!imageUrl) throw new Error('source_url is empty');

const imageHtml = `\n<figure class="wp-block-image size-full">\n  <img src="${imageUrl}" alt="blog diagram" class="wp-image-${imageId}" style="max-width:100%;height:auto;" />\n</figure>`;

const updatedContent = existingContent + imageHtml;

return [{ json: { updatedContent } }];

function extractMedia(obj) {
  if (!obj) return [];
  if (Array.isArray(obj)) return obj.flatMap(extractMedia);
  if (obj.media && Array.isArray(obj.media)) return obj.media;
  return Object.values(obj).flatMap(extractMedia);
}

let allMedia = [];
for (const item of items) {
  const found = extractMedia(item.json);
  allMedia.push(...found);
}

const unique = [];
const seen = new Set();
for (const media of allMedia) {
  if (!media?.image?.generatedImage?.fifeUrl) continue;
  if (!seen.has(media.name)) {
    seen.add(media.name);
    unique.push(media);
  }
}

return unique.map(media => ({
  json: {
    mediaId: media.name || null,
    prompt: media.image?.generatedImage?.prompt || null,
    url: media.image?.generatedImage?.fifeUrl || null
  }
}));

